import { startStagedRequest } from '../shared/deadline-stages.mjs';

export function handleRequest(options) {
  return startStagedRequest({ ...options, timeout: 100, resetAfterSetup: false });
}

/** A deterministic logical clock. Units are not elapsed milliseconds. */
export class ManualClock {
  now = 0;
  #nextId = 0;
  #timers = new Map();

  schedule(delay, callback) {
    if (!Number.isFinite(delay) || delay < 0) throw new Error('Invalid delay');
    const id = ++this.#nextId;
    this.#timers.set(id, { at: this.now + delay, callback });
    return () => this.#timers.delete(id);
  }

  advanceTo(time) {
    if (!Number.isFinite(time) || time < this.now) throw new Error('Clock cannot go backwards');
    while (true) {
      const next = [...this.#timers].filter(([, timer]) => timer.at <= time)
        .sort((a, b) => a[1].at - b[1].at || a[0] - b[0])[0];
      if (!next) break;
      this.now = next[1].at;
      this.#timers.delete(next[0]);
      next[1].callback();
    }
    this.now = time;
  }

  get pendingTimers() { return this.#timers.size; }
}

/** Synthetic setup/work phases; all times are logical clock units. */
export function startStagedRequest({ clock, signal, setupDuration = 80, workDuration = 60,
  timeout = 100, resetAfterSetup = false, failPhase }) {
  let result;
  let cancelPhase = () => {};
  let cancelDeadline = () => {};
  let resolveResponse;
  const response = new Promise(resolve => { resolveResponse = resolve; });
  const stats = { setupStarted: 0, workStarted: 0, active: 0 };
  const finish = status => {
    if (result) return;
    result = { status, at: clock.now };
    cancelPhase(); cancelDeadline();
    signal?.removeEventListener('abort', onAbort);
    stats.active = 0;
    resolveResponse(result);
  };
  const onAbort = () => finish('cancelled');
  const armDeadline = () => { cancelDeadline = clock.schedule(timeout, () => finish('timed-out')); };
  if (signal?.aborted) onAbort();
  else {
    signal?.addEventListener('abort', onAbort, { once: true });
    if (!resetAfterSetup) armDeadline();
    stats.setupStarted++; stats.active = 1;
    cancelPhase = clock.schedule(setupDuration, () => {
      if (failPhase === 'setup') { finish('error'); return; }
      if (resetAfterSetup) armDeadline();
      stats.workStarted++;
      cancelPhase = clock.schedule(workDuration, () => finish(failPhase === 'work' ? 'error' : 'ok'));
    });
  }
  return { response, stats, get result() { return result; } };
}

